package com.keyforge.nativeload;
import com.fasterxml.jackson.databind.*;import java.time.Instant;import java.util.*;
final class NativeWorkgroupMembershipParser {private final ObjectMapper m=new ObjectMapper();NativeWorkgroupMembershipPage parse(String b){try{JsonNode root=m.readTree(b);if(root==null||!root.isObject()||!root.path("rows").isArray()||!root.path("nextStart").canConvertToInt()||!root.path("done").isBoolean())throw new NativeImportException("Unexpected native WorkgroupMembership response: "+(b==null?"<null>":b.substring(0,Math.min(b.length(),300))));if(root.has("error"))throw new NativeImportException("Native workgroup membership endpoint error: "+root.path("error"));List<NativeWorkgroupMembershipRecord>out=new ArrayList<>();for(JsonNode n:root.path("rows")){NativeWorkgroupMembershipRecord r=new NativeWorkgroupMembershipRecord();r.workgroupId=text(n,"workgroupId");r.workgroupName=text(n,"workgroupName");r.identityId=text(n,"identityId");r.identityName=text(n,"identityName");r.firstName=text(n,"firstName");r.lastName=text(n,"lastName");r.srcSystem=text(n,"srcSystem");r.runId=text(n,"extractionRunId");r.memberIsWorkgroup=n.path("memberIsWorkgroup").isBoolean()?n.path("memberIsWorkgroup").asBoolean():null;try{r.extractedAt=Instant.parse(text(n,"extractedAt"));}catch(Exception ignored){}out.add(r);}return new NativeWorkgroupMembershipPage(out,root.path("nextStart").asInt(-1),root.path("done").asBoolean(false));}catch(NativeImportException e){throw e;}catch(Exception e){throw new NativeImportException("Cannot parse native membership response",e);}}private static String text(JsonNode n,String f){return n.path(f).isMissingNode()||n.path(f).isNull()?null:n.path(f).asText();}}
